#pragma once

#include <juce_core/juce_core.h>

namespace defeedback
{
inline juce::String remoteControlPageHtml()
{
    return R"DEFEEDBACK_HTML(<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#101316">
<title>DeFeedback Live Remote</title>
<style>
:root{color-scheme:dark;--bg:#101316;--panel:#1b2025;--line:#343c44;--text:#edf2f5;--muted:#9ba8b2;--green:#47d18c;--amber:#ffb454;--red:#ff5d62;--blue:#55b6df}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select{font:inherit;color:inherit}button,select,input[type=text],input[type=password]{background:#222a30;border:1px solid #52606a;border-radius:6px;min-height:38px;padding:7px 10px}button{font-weight:700;cursor:pointer}button:hover{filter:brightness(1.12)}button:disabled{cursor:not-allowed;opacity:.45}.wrap{max-width:1800px;margin:auto;padding:18px}.top{display:flex;gap:16px;align-items:center;margin-bottom:14px}.brand{font-size:25px;font-weight:850;letter-spacing:.02em}.sub{color:var(--muted)}.connection{margin-left:auto;padding:6px 10px;border-radius:999px;background:#263038;color:var(--muted);font-size:12px;font-weight:750}.connection.ok{background:#173d2e;color:#aaf0cc}.connection.bad{background:#5b2528;color:#ffc4c5}.panel{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:14px;margin-bottom:12px}.setup{display:grid;grid-template-columns:minmax(220px,2.2fr) 110px 130px auto auto;gap:12px;align-items:end}.field label,.small-title{display:block;color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.06em;margin:0 0 5px}.field select{width:100%}.button-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.engine{background:#6e4d24}.engine.start{background:#236b4b}.master{background:#672d31;min-width:190px}.master.muted{background:#b33f45}.danger{background:#7d3035}.secondary{background:#29343b}.metrics{display:flex;gap:20px;justify-content:flex-end;color:var(--muted);font-weight:750;margin-top:12px}.metrics b{color:var(--text)}.prefs{display:flex;gap:18px;margin-top:10px;color:var(--muted);font-size:12px}.prefs label{display:flex;gap:7px;align-items:center}.prefs input{accent-color:var(--green)}.notice{padding:10px 14px;border-radius:7px;text-align:center;font-weight:800;background:#173d2e;color:#aaf0cc;margin-bottom:12px}.notice.warn{background:#65421d;color:#ffddb0}.notice.error{background:#5b2528;color:#ffc4c5}.rack-head{display:flex;gap:12px;align-items:center;margin-bottom:10px}.rack-head h2{font-size:14px;margin:0}.rack-head .hint{color:var(--muted);font-size:12px}.rack-head button{margin-left:auto}.lane{display:grid;grid-template-columns:30px minmax(110px,1.05fr) minmax(145px,1.25fr) 80px minmax(190px,2fr) 78px 82px 80px minmax(145px,1.25fr) 112px 42px;gap:8px;align-items:center;border:1px solid color-mix(in srgb,var(--accent) 38%,transparent);border-left:5px solid var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--bg));border-radius:7px;padding:9px 8px;margin-bottom:8px}.lane.processed{--accent:var(--green)}.lane.bypass{--accent:var(--amber)}.lane.muted,.lane.error{--accent:var(--red)}.lane.stopped{--accent:var(--muted)}.num{color:var(--muted);font-weight:800;text-align:center}.lane input[type=text],.lane select{width:100%;min-width:0}.meter{height:10px;border-radius:4px;background:#090b0c;overflow:hidden}.meter>i{display:block;width:0;height:100%;background:var(--green);border-radius:4px;transition:width .09s linear}.strength{display:grid;grid-template-columns:1fr 48px;gap:7px;align-items:center}.strength input{width:100%;accent-color:var(--blue)}.strength output{font-size:12px;font-variant-numeric:tabular-nums;text-align:right}.toggle.on{background:#8b3439;color:#fff}.toggle.bypass-on{background:#7b531f;color:#fff}.state{font-size:11px;font-weight:850;color:var(--accent)}.remove{color:var(--red);padding:6px}.labels{display:grid;grid-template-columns:30px minmax(110px,1.05fr) minmax(145px,1.25fr) 80px minmax(190px,2fr) 78px 82px 80px minmax(145px,1.25fr) 112px 42px;gap:8px;padding:0 13px 6px;color:var(--muted);font-size:9px;font-weight:800;letter-spacing:.04em}.center{text-align:center}.login-shell{min-height:100vh;display:grid;place-items:center;padding:20px}.login{width:min(430px,100%);background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:25px}.login h1{font-size:23px;margin:0 0 6px}.login p{color:var(--muted);line-height:1.45}.login input{width:100%;font-size:24px;letter-spacing:.16em;text-align:center;margin:8px 0 10px}.login button{width:100%;background:#236b4b}.login .error-text{min-height:20px;color:#ffc4c5;font-size:12px}.foot{color:var(--muted);font-size:11px;line-height:1.5;margin-top:14px}.hidden{display:none!important}
@media(max-width:1120px){.setup{grid-template-columns:1fr 1fr 1fr}.setup .device{grid-column:span 2}.setup .button-row{grid-column:1/-1}.labels{display:none}.lane{grid-template-columns:30px 1fr 1fr 90px}.lane>*{min-width:0}.lane .name{grid-column:2/4}.lane .input-select{grid-column:1/3}.lane .input-meter{grid-column:3/5}.lane .strength{grid-column:1/5}.lane .mute{grid-column:1/3}.lane .bypass-button{grid-column:3/5}.lane .output-meter{grid-column:1/3}.lane .output-select{grid-column:3/5}.lane .state{grid-column:1/4}.lane .remove{grid-column:4}.metrics{justify-content:flex-start;flex-wrap:wrap}.top{align-items:flex-start;flex-wrap:wrap}.connection{margin-left:0}}
@media(max-width:600px){.wrap{padding:10px}.setup{grid-template-columns:1fr 1fr}.setup .device{grid-column:1/-1}.setup .button-row{grid-column:1/-1}.button-row button{flex:1}.metrics{gap:12px}.lane{grid-template-columns:1fr 1fr}.lane .num{display:none}.lane .name{grid-column:1/3}.lane .input-select,.lane .output-select,.lane .strength{grid-column:1/3}.lane .input-meter{grid-column:1/3}.lane .mute{grid-column:1}.lane .bypass-button{grid-column:2}.lane .output-meter{grid-column:1/3}.lane .state{grid-column:1}.lane .remove{grid-column:2}.rack-head{flex-wrap:wrap}.rack-head button{margin-left:0;width:100%}}
</style>
</head>
<body>
<section id="loginShell" class="login-shell">
  <form id="loginForm" class="login">
    <h1>DeFeedback Live</h1>
    <p>Enter the eight-digit LAN access code shown in the Mac app. This remote has full control of live audio.</p>
    <input id="code" type="password" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" autocomplete="one-time-code" aria-label="Access code" required>
    <button type="submit">CONNECT</button>
    <div id="loginError" class="error-text" role="alert"></div>
    <div class="foot">Use only on a trusted private network. Keep an independent hardware or console mute available.</div>
  </form>
</section>
<main id="app" class="wrap hidden">
  <header class="top"><div><div class="brand">DEFEEDBACK LIVE</div><div class="sub">Full-control LAN remote</div></div><div id="connection" class="connection">CONNECTING</div></header>
  <section class="panel">
    <div class="setup">
      <div class="field device"><label>CORE AUDIO DEVICE</label><select id="device"></select></div>
      <div class="field"><label>SAMPLE RATE</label><select id="rate"></select></div>
      <div class="field"><label>BUFFER</label><select id="buffer"></select></div>
      <div class="button-row"><button id="refresh" class="secondary">REFRESH DEVICES</button><button id="engine" class="engine">STOP ENGINE</button><button id="master" class="master">MUTE ALL OUTPUTS</button></div>
      <div class="button-row"><button id="reset" class="secondary">RESET XRUNS</button><button id="logout" class="secondary">LOG OUT</button></div>
    </div>
    <div class="metrics"><span>LATENCY <b id="latency">--</b></span><span>CPU <b id="cpu">--</b></span><span>XRUNS <b id="xruns">--</b></span></div>
    <div class="prefs"><label><input id="autoStart" type="checkbox"> Auto-start audio</label><label><input id="launchAtLogin" type="checkbox"> Launch at login</label></div>
  </section>
  <div id="notice" class="notice">CONNECTING TO AUDIO ENGINE</div>
  <section class="panel">
    <div class="rack-head"><div><h2>MONO PROCESSING LANES</h2><div id="hint" class="hint"></div></div><button id="add" class="secondary">+ ADD LANE</button></div>
    <div class="labels"><span>#</span><span>NAME</span><span>INPUT</span><span class="center">IN</span><span>STRENGTH</span><span class="center">MUTE</span><span class="center">BYPASS</span><span class="center">OUT</span><span>OUTPUT</span><span>STATE</span><span></span></div>
    <div id="lanes"></div>
  </section>
  <div id="plugin" class="foot"></div>
  <div class="foot">Independent third-party host; not affiliated with or endorsed by Alpha Labs LLC. Engineering preview, supplied without warranty. Use at your own risk.</div>
</main>
<script>
(()=>{
const $=id=>document.getElementById(id), tokenKey='defeedbackRemoteToken';
let token=sessionStorage.getItem(tokenKey)||'',lastLaneSignature='',lastSetupSignature='',pollTimer=0,lastState=null,connected=false;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(token)headers.Authorization='Bearer '+token;const response=await fetch(path,{...options,headers,cache:'no-store'});if(response.status===401&&path!='/api/login'){logout();throw new Error('Authentication expired');}const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Request failed');return data}
function logout() {const oldToken=token;token='';sessionStorage.removeItem(tokenKey);$('app').classList.add('hidden');$('loginShell').classList.remove('hidden');$('code').focus();if(oldToken)fetch('/api/logout',{method:'POST',headers:{Authorization:'Bearer '+oldToken},cache:'no-store'}).catch(()=>{})}
$('loginForm').addEventListener('submit',async event=>{event.preventDefault();$('loginError').textContent='';try{const data=await api('/api/login',{method:'POST',body:JSON.stringify({code:$('code').value})});token=data.token;sessionStorage.setItem(tokenKey,token);$('code').value='';$('loginShell').classList.add('hidden');$('app').classList.remove('hidden');await poll()}catch(error){$('loginError').textContent=error.message}});
$('logout').onclick=logout;
async function command(type,values={}){try{await api('/api/command',{method:'POST',body:JSON.stringify({type,...values})});setTimeout(poll,70)}catch(error){setConnection(false,error.message)}}
function setConnection(ok,message=''){connected=ok;$('connection').textContent=ok?'LIVE':(message||'DISCONNECTED');$('connection').className='connection '+(ok?'ok':'bad')}
function syncSelect(element,items,value,label){const signature=JSON.stringify(items);if(element.dataset.signature!==signature){element.innerHTML=items.map(item=>`<option value="${esc(item.value)}">${esc(item.label)}</option>`).join('');element.dataset.signature=signature}if(document.activeElement!==element)element.value=String(value);element.disabled=!items.length;element.title=label}
function laneClass(lane,state){if(!state.engineRunning)return'stopped';if(state.masterMuted||lane.pluginMuted)return'muted';if(/invalid|duplicate|error/i.test(lane.status))return'error';if(lane.dry||lane.dryFallback)return'bypass';return'processed'}
function renderLanes(state){
const channelOptions=(channels,prefix,lane,property)=>channels.map((name,index)=>{const used=state.lanes.some(other=>other.id!==lane.id&&other[property]===index);return `<option value="${index}" ${used?'disabled':''}>${prefix} ${index+1} - ${esc(name)}</option>`}).join('');
$('lanes').innerHTML=state.lanes.map((lane,index)=>{const inputOptions=channelOptions(state.inputChannels,'Input',lane,'inputChannel'),outputOptions=channelOptions(state.outputChannels,'Output',lane,'outputChannel');return `<div class="lane ${laneClass(lane,state)}" data-id="${lane.id}"><div class="num">${index+1}</div><input class="name" type="text" value="${esc(lane.name)}" aria-label="Lane name"><select class="input-select" aria-label="Input channel">${inputOptions}</select><div class="meter input-meter" title="Input level"><i></i></div><div class="strength"><input type="range" min="0" max="100" step="0.1" value="${(lane.strength*100).toFixed(1)}" ${lane.strengthAvailable?'':'disabled'} aria-label="Strength"><output>${Math.round(lane.strength*100)}%</output></div><button class="toggle mute ${lane.pluginMuted?'on':''}" aria-pressed="${lane.pluginMuted}" ${lane.pluginMuteAvailable?'':'disabled'}>MUTE</button><button class="toggle bypass-button ${lane.dry?'bypass-on':''}" aria-pressed="${lane.dry}">BYPASS</button><div class="meter output-meter" title="Output level"><i></i></div><select class="output-select" aria-label="Output channel">${outputOptions}</select><div class="state">${esc(lane.status)}</div><button class="remove" aria-label="Remove lane">X</button></div>`}).join('');
state.lanes.forEach(lane=>{const row=document.querySelector(`.lane[data-id="${lane.id}"]`);if(!row)return;const inputSelect=row.querySelector('.input-select'),outputSelect=row.querySelector('.output-select'),mute=row.querySelector('.mute'),bypass=row.querySelector('.bypass-button');inputSelect.value=lane.inputChannel;outputSelect.value=lane.outputChannel;const name=row.querySelector('.name');const updateRoute=()=>command('updateLane',{id:lane.id,name:name.value,inputChannel:Number(inputSelect.value),outputChannel:Number(outputSelect.value),dry:bypass.classList.contains('bypass-on')});const showExpectedState=(pluginMuted,dry)=>{row.classList.remove('processed','bypass','muted','error','stopped');row.classList.add(laneClass({...lane,pluginMuted,dry},state));row.querySelector('.state').textContent=!state.engineRunning?'ENGINE STOPPED':state.masterMuted?'OUTPUT MUTED':pluginMuted?'PLUGIN MUTED':dry?'BYPASSED':'PROCESSED'};name.onblur=updateRoute;name.onkeydown=e=>{if(e.key==='Enter')name.blur()};inputSelect.onchange=()=>{updateRoute();inputSelect.blur()};outputSelect.onchange=()=>{updateRoute();outputSelect.blur()};const slider=row.querySelector('input[type=range]'),output=row.querySelector('output');let strengthTimer=0;slider.oninput=()=>{output.value=Math.round(slider.value)+'%';clearTimeout(strengthTimer);strengthTimer=setTimeout(()=>command('setLaneStrength',{id:lane.id,value:Number(slider.value)/100,commit:false}),100)};slider.onchange=()=>{slider.blur();command('setLaneStrength',{id:lane.id,value:Number(slider.value)/100,commit:true})};mute.onclick=()=>{const next=!mute.classList.contains('on');mute.classList.toggle('on',next);mute.setAttribute('aria-pressed',String(next));showExpectedState(next,bypass.classList.contains('bypass-on'));mute.blur();command('setLanePluginMuted',{id:lane.id,muted:next})};bypass.onclick=()=>{const next=!bypass.classList.contains('bypass-on');bypass.classList.toggle('bypass-on',next);bypass.setAttribute('aria-pressed',String(next));showExpectedState(mute.classList.contains('on'),next);bypass.blur();command('updateLane',{id:lane.id,name:name.value,inputChannel:Number(inputSelect.value),outputChannel:Number(outputSelect.value),dry:next})};row.querySelector('.remove').onclick=()=>{if(confirm(`Remove ${lane.name}?`))command('removeLane',{id:lane.id})}})}
function updateMeters(state){state.lanes.forEach(lane=>{const row=document.querySelector(`.lane[data-id="${lane.id}"]`);if(!row)return;row.querySelector('.input-meter i').style.width=(Math.sqrt(Math.max(0,lane.inputPeak))*100).toFixed(1)+'%';row.querySelector('.output-meter i').style.width=(Math.sqrt(Math.max(0,lane.outputPeak))*100).toFixed(1)+'%'})}
function render(state){lastState=state;setConnection(true);$('latency').textContent=state.latencyMs.toFixed(1)+' ms';$('cpu').textContent=state.cpuPercent.toFixed(1)+'%';$('xruns').textContent=state.xruns;$('plugin').textContent=state.pluginDiagnostic;$('hint').textContent=`${state.lanes.length} lanes - ${state.capacity} available I/O pairs`;$('notice').textContent=state.message||'REMOTE CONNECTED';$('notice').className='notice '+(state.messageError?'error':(/bypass|stopped|muted/i.test(state.message)?'warn':''));$('autoStart').checked=state.autoStart;$('launchAtLogin').checked=state.launchAtLogin;const engine=$('engine');engine.textContent=state.engineRunning?'STOP ENGINE':'START ENGINE';engine.className='engine '+(state.engineRunning?'':'start');const master=$('master');master.textContent=state.masterMuted?'OUTPUTS MUTED - UNMUTE':'MUTE ALL OUTPUTS';master.className='master '+(state.masterMuted?'muted':'');const setupSignature=JSON.stringify([state.devices,state.sampleRates,state.bufferSizes]);if(setupSignature!==lastSetupSignature){syncSelect($('device'),state.devices.map((name,index)=>({value:index,label:name})),state.selectedDevice,'Core Audio device');syncSelect($('rate'),state.sampleRates.map(rate=>({value:rate,label:(rate/1000).toFixed(1)+' kHz'})),state.selectedSampleRate,'Sample rate');syncSelect($('buffer'),state.bufferSizes.map(size=>({value:size,label:size+' samples'})),state.selectedBufferSize,'Buffer size');lastSetupSignature=setupSignature}else{if(document.activeElement!==$('device'))$('device').value=String(state.selectedDevice);if(document.activeElement!==$('rate'))$('rate').value=String(state.selectedSampleRate);if(document.activeElement!==$('buffer'))$('buffer').value=String(state.selectedBufferSize)}const laneSignature=JSON.stringify([state.inputChannels,state.outputChannels,state.engineRunning,state.masterMuted,state.message,state.messageError,state.lanes.map(l=>[l.id,l.name,l.inputChannel,l.outputChannel,l.dry,l.pluginMuted,Math.round(l.strength*1000),l.status,l.strengthAvailable,l.pluginMuteAvailable])]);const active=document.activeElement,editing=active&&active.closest&&active.closest('.lane')&&(active.matches('.name')||active.matches('input[type=range]'));if(laneSignature!==lastLaneSignature&&!editing){renderLanes(state);lastLaneSignature=laneSignature}updateMeters(state)}
async function poll(){clearTimeout(pollTimer);if(!token)return;try{render(await api('/api/state'))}catch(error){if(token)setConnection(false,error.message)}finally{if(token)pollTimer=setTimeout(poll,125)}}
$('refresh').onclick=()=>command('refreshDevices');$('reset').onclick=()=>command('resetXRuns');$('add').onclick=()=>command('addLane');$('device').onchange=()=>command('selectDevice',{index:Number($('device').value)});$('rate').onchange=()=>command('setSampleRate',{value:Number($('rate').value)});$('buffer').onchange=()=>command('setBufferSize',{value:Number($('buffer').value)});$('autoStart').onchange=()=>command('setAutoStart',{enabled:$('autoStart').checked});$('launchAtLogin').onchange=()=>command('setLaunchAtLogin',{enabled:$('launchAtLogin').checked});$('engine').onclick=()=>{if(!lastState)return;if(lastState.engineRunning||confirm('Start the complete audio engine remotely?'))command('setEngineRunning',{running:!lastState.engineRunning})};$('master').onclick=()=>{if(!lastState)return;if(!lastState.masterMuted||confirm('Unmute every physical output now? Confirm the complete signal path is safe.'))command('setMasterMuted',{muted:!lastState.masterMuted})};
if(token){$('loginShell').classList.add('hidden');$('app').classList.remove('hidden');poll()}else $('code').focus();
})();
</script>
</body>
</html>)DEFEEDBACK_HTML";
}
}
